  <table class="header-table">
    <tr>
      <td>
        <h1 class="header-logo">${lt(o)}</h1>
        <p class="header-subtitle">Executive Daily Cash Register &amp; Till Closing Statement (\u06CC\u0648\u0645\u06CC\u06C1 \u0631\u0648\u0632\u0646\u0627\u0645\u0686\u06C1)</p>
      </td>
      <td class="meta-box">
        <div><strong>Closing Date:</strong> ${lt(e.todayStr)} PKT</div>
        <div><strong>Register Month:</strong> ${lt(e.currentMonth)}</div>
        <div><strong>Closing Status:</strong> ${lt(e.statusLabel)}</div>
      </td>
    </tr>
  </table>

